// Any unhandled failure / timeout in the MMVH workflows lands here and is logged as NEEDS_ATTENTION
const e = $input.first().json;
const ex = e.execution || {};
const msg = String((ex.error && (ex.error.message || ex.error.description)) || 'unknown error').slice(0, 300);
const row = [ 'n/a (execution ' + (ex.id || '?') + ')', new Date().toISOString(), '', 'UNKNOWN', 'NEEDS_ATTENTION',
  'Workflow failure - staff must review this execution. Nothing should be assumed booked.', '', String(ex.id || ''), 'error-workflow',
  'Workflow: ' + ((e.workflow && e.workflow.name) || '?') + ' | last node: ' + (ex.lastNodeExecuted || '?') + ' | ' + msg + (ex.url ? ' | ' + ex.url : '') ];
return [{ json: { http: { url: 'https://sheets.googleapis.com/v4/spreadsheets/YOUR_SPREADSHEET_ID/values/' + encodeURIComponent('CallLog!A:J') + ':append?valueInputOption=RAW&insertDataOption=INSERT_ROWS', body: { values: [row] } } } }];
